<?php
namespace App\Extensions\ChatbotAgent\System\Services;
use App\Extensions\Chatbot\System\Models\ChatbotConversation; use App\Extensions\Chatbot\System\Models\ChatbotHistory; use App\Extensions\Chatbot\System\Services\AIRuntime; use Illuminate\Support\Str;
class UnifiedInboxService { public function __construct(private readonly AIRuntime $ai){} public function query(array $f){$q=ChatbotConversation::query()->with(['customer','lastMessage','customerTags']);$q->when($f['q']??null,fn($b,$v)=>$b->where(fn($x)=>$x->where('conversation_name','like',"%$v%")->orWhere('summary','like',"%$v%")));$q->when($f['assigned_to']??null,fn($b,$v)=>$b->where('assigned_to',$v));$q->when($f['priority']??null,fn($b,$v)=>$b->where('priority',$v));$q->when($f['status']??null,fn($b,$v)=>$b->where('ticket_status',$v));return $q->latest('last_activity_at')->paginate((int)($f['per_page']??30));} public function assign(ChatbotConversation $c,?int $userId):ChatbotConversation{$c->forceFill(['assigned_to'=>$userId])->save();return$c->refresh();} public function note(ChatbotConversation $c,string $text,?int $userId):ChatbotHistory{return $c->histories()->create(['user_id'=>$userId,'chatbot_id'=>$c->chatbot_id,'message_id'=>(string) Str::uuid(),'role'=>'assistant','message'=>$text,'is_internal_note'=>true,'created_at'=>now()]);} public function translate(string $text,string $locale):string{return $this->ai->translate($text,$locale);} public function draft(ChatbotConversation $c):array{return $this->ai->draft(['summary'=>$c->summary,'messages'=>$c->histories()->latest('id')->limit(20)->get()->reverse()->values()->toArray()]);} }
